// Message Generator Function
const scenarios = {
  job_seeker: {
    greetings: ['Hi {name}', 'Hello {name}', 'Hi there {name}'],
    intros: [
      'I came across your profile while researching {company} and was impressed by your work in talent acquisition.',
      "I noticed you're leading talent acquisition at {company}, and I wanted to reach out.",
      'Your experience in HR at {company} caught my attention.'
    ],
    value_props: [
      "I'm a Software Engineer with 5+ years of experience in full-stack development, and I'm actively exploring new opportunities.",
      'As a developer specializing in cloud architecture and modern web technologies, I\'m interested in learning more about opportunities at {company}.',
      'I bring extensive experience in building scalable applications and am particularly drawn to {company}\'s mission.'
    ],
    ctas: [
      'Would you be open to a brief conversation about current or future opportunities?',
      "I'd love to connect and learn more about your team's needs.",
      'Would you have 15 minutes for a quick chat about potential openings?'
    ],
    closings: [
      'Thanks for your time, and I look forward to connecting!',
      'Looking forward to hearing from you!',
      'Thank you for considering my request!'
    ]
  },
  networking: {
    greetings: ['Hi {name}', 'Hello {name}'],
    intros: [
      'I noticed we both work in the tech space and wanted to connect.',
      'Your work at {company} has been really impressive, especially in talent development.',
      "I've been following {company}'s innovative approach to hiring and wanted to reach out."
    ],
    value_props: [
      "I'm always looking to expand my network with talented HR professionals.",
      "I'd love to exchange insights about current trends in talent acquisition.",
      'I think we could have some interesting conversations about the evolving HR landscape.'
    ],
    ctas: [
      'Would you be open to connecting?',
      "I'd love to add you to my professional network.",
      "Let's connect and stay in touch!"
    ],
    closings: [
      'Best regards!',
      'Thanks for connecting!',
      'Looking forward to staying in touch!'
    ]
  }
};

function selectRandom(array) {
  return array[Math.floor(Math.random() * array.length)];
}

function generateMessage(profile, scenario = 'job_seeker') {
  const templates = scenarios[scenario] || scenarios.job_seeker;
  const firstName = profile.name.split(' ')[0];
  const company = profile.company || 'your company';

  const greeting = selectRandom(templates.greetings).replace('{name}', firstName);
  const intro = selectRandom(templates.intros).replace('{company}', company);
  const valueProp = selectRandom(templates.value_props).replace('{company}', company);
  const cta = selectRandom(templates.ctas).replace('{company}', company);
  const closing = selectRandom(templates.closings);

  const message = `${greeting},\n\n${intro}\n\n${valueProp}\n\n${cta}\n\n${closing}`;

  return {
    recipient_name: profile.name,
    recipient_title: profile.title,
    recipient_url: profile.profile_url,
    recipient_location: profile.location,
    message: message,
    char_count: message.length,
    scenario: scenario,
    generated_at: new Date().toISOString()
  };
}

// Process each profile
const profile = $input.item.json;
const scenario = $node["Webhook Trigger"].json.body.scenario || 'job_seeker';
const messageData = generateMessage(profile, scenario);

return messageData;

